(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.015+t*0.15)*8 + Math.cos((y+w1y)*0.02-t*0.1)*6;
  const w2y = Math.cos((y+w1y)*0.018-t*0.12)*8 + Math.sin((x+w1x)*0.012+t*0.18)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*45, 0.085, 1.8],
    [200+Math.sin(t*0.7+6)*90, 220+Math.cos(t*0.5+5)*60, 0.095, 2.4]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    wS += Math.sin(d*f*1.3 - t*sp*0.4 + 2.8) * 0.6;
  }
  const act = aS/9, inh = iS/9, wav = wS/9;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.07+sy*0.09-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const breath = 1 + Math.sin(t*0.4)*0.15;
  const spiral = (Math.sin(dist*0.05*breath-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4 + Math.sin(dist*0.03-ang*2+t*0.8)*0.2;
  const reaction1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const reaction2 = Math.tanh((wav + act*0.4 - inh*0.3 + spiral*0.5)*1.8);
  const merged = reaction1*0.65 + reaction2*0.35;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.tanh((Math.sin(sx*0.12+1)*Math.cos(sy*0.13-0.5) + Math.sin((sx-sy)*0.08+t*0.7)*0.4)*1.2)*0.2;
  const blend = merged*0.6 + (cell+cell2)*0.2 + spiral*0.2;
  const v = blend*0.5+0.5;
  const pal = [[6,12,52],[12,48,88],[18,95,115],[35,155,140],[120,195,160],[210,200,80],[225,145,65],[200,85,75],[140,45,85],[70,25,70],[25,15,58],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.8+Math.sin(merged*Math.PI)*0.2;
  const edge = Math.abs(merged)>0.65?1.12:(Math.abs(merged)<0.15?0.92:1.0);
  const glow = Math.max(0, 1-Math.abs(merged)*2.5)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*80)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*60)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*40)|0
  ];
}
